from contextlib import contextmanager
from ute_wtssim.interface import ute_wtssim as ute_wtssim_interface
from .ssh_adapter import SSHAdapter
from ute_wtssim.wts.egate import Egate, PortIsReserved
try:
    from unittest.mock import patch
except ImportError:
    from mock import patch


class epcsim(ute_wtssim_interface):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    @contextmanager
    def ssh_adaptation(self):
        """ Perform method switcheroo, that will make ute_wtssim use TAF's SSH.

        This context manager uses _adapter_creator method from below.
        After exiting context, the class will be restored to its previous
        state.
        """
        old_method = self._create_ssh_client_from_settings
        self._create_ssh_client_from_settings = self._adapter_creator
        yield
        self._create_ssh_client_from_settings = old_method

    def _adapter_creator(self, settings):
        """ Create SSHAdapter using ConnectionSettings

        This method is meant to take place of _create_ssh_client_from_settings
        when setting up persistent edaemon or egate process.
        """

        return SSHAdapter(settings)

    def _teardown_mock(self):
        """
        This method will be inserted into Egate and Edaemon instances, to
        prevent them from executing their teardowns (when persistent=True).
        """
        pass

    def setup_egate(self, egate_port, host_ip='127.0.0.1', tool_dir=None,
                    persistent=False, root_flag=False, **kwargs):
        """
        Extension of 'Setup Egate' keyword from ute_wtssim.

        See documentation of ute_wtssim library for more information.

        This keyword provides additional 'persistent' and 'root_flag' flags,
        that if set to True:
            * persistent: will make the egate process stay up after finishing
              the test.
            * root_flag: will make the egate process start with '--root' flag
        By default both are set to False.

        All of the other arguments are the same as in ute_wtssim, with an
        exception of 'ssh_prompt' (kwargs), which is ignored if 'persistent' is
        set to True.
        """
        if root_flag:
            self._substitute_egate_setup()
        if not persistent:
            super(epcsim, self).setup_egate(egate_port, host_ip, tool_dir,
                                            **kwargs)
        else:
            with self.ssh_adaptation():
                super(epcsim, self).setup_egate(egate_port, host_ip, tool_dir,
                                                **kwargs)

        alias = kwargs.get('alias')
        new_state_machine = self.wts_store.get(alias)
        self._mock_teardowns_in_wts_state_machine(new_state_machine)
        if root_flag:
            self.egate_patcher.stop()

    def _substitute_egate_setup(self):
        class RootFlagEgate(Egate):
            def _start_egate(self):
                if not self._is_tcp_port_free(self._port):
                    raise PortIsReserved("Egate", self._port)
                cmd = self._extend_lua_path()
                if not self._pid:
                    cmd += "cd {}; ./egate --root --port {}"
                    cmd = cmd.format(self._tool_dir, self._port)
                    out, err, rc = self._client.execute_command(cmd)
                    self._pid = self._get_egate_pid(out, err)
        patch_path = 'ute_wtssim.wts.egate.Egate'
        self.egate_patcher = patch(patch_path,
                                   new_callable=lambda: RootFlagEgate)
        self.egate_patcher.start()

    def setup_edaemon(self, edaemon_port, host_ip='127.0.0.1', tool_dir=None,
                      persistent=False, **kwargs):
        """
        Extension of 'Setup Edaemon' keyword from ute_wtssim.

        See documentation of ute_wtssim library for more information.

        This keyword provides additional 'persistent' flag, that if set to True
        will make the edaemon process stay up after finishing the test. By
        default it is set to False.

        All of the other arguments are the same as in ute_wtssim, with an
        exception of 'ssh_prompt' (kwargs), which is ignored.
        """
        if not persistent:
            super(epcsim, self).setup_edaemon(edaemon_port, host_ip, tool_dir,
                                              **kwargs)
        else:
            with self.ssh_adaptation():
                super(epcsim, self).setup_edaemon(edaemon_port, host_ip,
                                                  tool_dir, **kwargs)

        alias = kwargs.get('alias')
        new_state_machine = self.edaemon_store.get(alias)
        self._mock_teardowns_in_wts_state_machine(new_state_machine)

    def _mock_teardowns_in_wts_state_machine(self, state_machine):
        for egate_instance in state_machine.egates:
            self._mock_instance_teardown(egate_instance)
        for edaemon_instance in state_machine.edaemons:
            self._mock_instance_teardown(edaemon_instance)

    def _mock_instance_teardown(self, instance):
        instance.teardown = self._teardown_mock
